entries[216681] = { ["name"] = "Teufelswinde", ["text"] = "40 Meter Reichweite\nSofort\nEiskalte Winde stoßen Euch zurück." }
entries[216682] = { ["name"] = "Abstoßung", ["text"] = "40 Meter Reichweite\nSofort\nBeschwört eine Teufelskugel, die allen Gegnern in der Nähe alle 2.5 Sek. Feuerschaden zufügt." }
entries[216683] = { ["name"] = "Gedanken beherrschen" }
entries[216685] = { ["name"] = "Flammen von Argus", ["text"] = "Sofort\nDie Flammen von Argus brechen für 1 Min. unter allen Spielercharakteren aus dem Boden hervor, die 'Brandmal von Argus' auslösen. Dieser Effekt fügt allen Spielercharakteren innerhalb des Zielbereichs alle 0.5 Sek. 2371 Feuerschaden zu." }
entries[216686] = { ["name"] = "Erschaffen" }
entries[216687] = { ["name"] = "Gedanken beherrschen" }
entries[216688] = { ["name"] = "Ende der Nacht", ["text"] = "Sofort\nDie illusionäre Nacht verschlingt alle Spielercharaktere, die nicht unter der Wirkung von 'Essenz der Nacht' stehen, und verursacht 111951 Schattenschaden." }
entries[216689] = { ["name"] = "Dämonischer Boden" }
entries[216690] = { ["name"] = "Gedankenkontrolle" }
entries[216691] = { ["name"] = "Gedankenkontrolle" }
entries[216692] = { ["name"] = "Blendendes Licht", ["text"] = "100 Meter Reichweite\nKanalisiert (Wirken in 0 sek.)\nBetäubt." }
entries[216693] = { ["name"] = "Unbeugsamer Wille", ["text"] = "Wirken in 10 sek.\nRuft die Macht des Aschenbringers an, um Euch Balnazzars Gedankenkontrolle zu entziehen." }
entries[216694] = { ["name"] = "Gespräch eröffnen" }
entries[216695] = { ["name"] = "Gepeinigte Seelen", ["text"] = "60 Meter Reichweite\nSofort\nAktiviert 'Seelen ernten', um alle von Ulthalesh gesammelten gepeinigten Seelen zu verzehren. Dies erhöht Euren Schaden um 10% und verdoppelt die Effekte sämtlicher anderen Boni von Ulthalesh für 5 Sek. pro verzehrter Seele." }
entries[216696] = { ["name"] = "Eiskristall" }
entries[216697] = { ["name"] = "Eisiger Impuls", ["text"] = "Sofort\nFügt Gegnern innerhalb von 5 Metern 29634 Frostschaden zu und betäubt sie für 1.5 Sek." }
entries[216698] = { ["name"] = "Seelen ernten", ["text"] = "Rang 1/ 0 Artefakt Boni\nSofort 5 sek. Abklingzeit\nBenötigt Ulthalesh, Sense der Totenwinde\nVerzehrt alle von Ulthalesh gesammelten gepeinigten Seelen, um Euren Schaden um 10% zu erhöhen und den Effekt aller anderen Eigenschaften von Ulthalesh pro verzehrter Seele 5 Sek. lang zu verdoppeln.\n\nUlthalesh sammelt von jedem Ziel, das Ihr tötet, gepeinigte Seelen und manchmal entflohene Seelen, die zuvor eingesammelt wurden." }
