entries[216708] = { ["name"] = "Sense der Totenwinde", ["text"] = "Sofort\nVerzehrt alle von Ulthalesh gesammelten gepeinigten Seelen, um Euren Schaden um 10% zu erhöhen und den Effekt aller anderen Eigenschaften von Ulthalesh pro verzehrter Seele 5 Sek. lang zu verdoppeln.\n\nUlthalesh sammelt von jedem Ziel, das Ihr tötet, gepeinigte Seelen und manchmal entflohene Seelen, die zuvor eingesammelt wurden." }
